-- Star schema for the SQL Analytics Lab retail dataset (SQLite dialect).
-- Grain of fact_order_line: one row per order line (an order can contain many lines).
-- dim_order_date is generated by the loader over a full 2023-2025 calendar.

PRAGMA foreign_keys = ON;

CREATE TABLE dim_customer (
    customer_id   TEXT PRIMARY KEY,
    customer_name TEXT NOT NULL,
    province      TEXT NOT NULL,
    signup_date   TEXT NOT NULL
);

CREATE TABLE dim_product (
    product_id   TEXT PRIMARY KEY,
    product_name TEXT NOT NULL,
    category     TEXT NOT NULL,
    unit_price   REAL NOT NULL,
    unit_cost    REAL NOT NULL
);

CREATE TABLE dim_order_date (
    date_key     TEXT PRIMARY KEY, -- ISO date, e.g. 2024-12-25
    year         INTEGER NOT NULL,
    month        INTEGER NOT NULL,
    day_of_month INTEGER NOT NULL,
    iso_week     INTEGER NOT NULL,
    month_name   TEXT NOT NULL,
    is_weekend   INTEGER NOT NULL  -- 1 = Sat/Sun, 0 = Mon-Fri
);

CREATE TABLE fact_order_line (
    line_id         TEXT PRIMARY KEY,
    order_id        TEXT NOT NULL,
    date_key        TEXT NOT NULL REFERENCES dim_order_date (date_key),
    customer_id     TEXT NOT NULL REFERENCES dim_customer (customer_id),
    product_id      TEXT NOT NULL REFERENCES dim_product (product_id),
    quantity        INTEGER NOT NULL,
    unit_price      REAL NOT NULL,
    discount_pct    REAL NOT NULL,
    discount_amount REAL NOT NULL,
    line_revenue    REAL NOT NULL, -- quantity * unit_price - discount_amount
    line_profit     REAL NOT NULL  -- line_revenue - quantity * product cost
);

CREATE INDEX idx_fact_date ON fact_order_line (date_key);
CREATE INDEX idx_fact_customer ON fact_order_line (customer_id);
CREATE INDEX idx_fact_product ON fact_order_line (product_id);

-- Monthly revenue, orders and units, straight off the star schema.
CREATE VIEW v_monthly_revenue AS
SELECT d.year,
       d.month,
       printf('%d-%02d', d.year, d.month) AS year_month,
       COUNT(DISTINCT f.order_id)         AS orders,
       SUM(f.quantity)                    AS units_sold,
       ROUND(SUM(f.line_revenue), 2)      AS revenue,
       ROUND(SUM(f.line_profit), 2)       AS profit
FROM fact_order_line AS f
JOIN dim_order_date AS d ON d.date_key = f.date_key
GROUP BY d.year, d.month;

-- Customer RFM (recency / frequency / monetary) with quartile scores and a segment.
-- Recency is measured in days from each customer's last order to the dataset's
-- most recent order date.
CREATE VIEW v_customer_rfm AS
WITH last_orders AS (
    SELECT f.customer_id,
           MAX(d.date_key)                    AS last_order_date,
           COUNT(DISTINCT f.order_id)         AS frequency,
           ROUND(SUM(f.line_revenue), 2)      AS monetary
    FROM fact_order_line AS f
    JOIN dim_order_date AS d ON d.date_key = f.date_key
    GROUP BY f.customer_id
), scored AS (
    SELECT c.customer_id,
           c.province,
           lo.last_order_date,
           CAST(julianday((SELECT MAX(last_order_date) FROM last_orders)) - julianday(lo.last_order_date) AS INTEGER)
               AS recency_days,
           lo.frequency,
           lo.monetary,
           NTILE(4) OVER (ORDER BY julianday((SELECT MAX(last_order_date) FROM last_orders)) - julianday(lo.last_order_date) DESC, c.customer_id)
               AS r_score, -- 4 = bought most recently
           NTILE(4) OVER (ORDER BY lo.frequency, c.customer_id)
               AS f_score, -- 4 = buys most often
           NTILE(4) OVER (ORDER BY lo.monetary, c.customer_id)
               AS m_score  -- 4 = spends most
    FROM last_orders AS lo
    JOIN dim_customer AS c ON c.customer_id = lo.customer_id
)
SELECT s.customer_id,
       s.province,
       s.last_order_date,
       s.recency_days,
       s.frequency,
       s.monetary,
       s.r_score,
       s.f_score,
       s.m_score,
       CASE
           WHEN s.r_score = 4 AND s.f_score >= 3 THEN 'Champions'
           WHEN s.r_score >= 3 AND s.f_score >= 3 THEN 'Loyal'
           WHEN s.m_score = 4 THEN 'Big Spenders'
           WHEN s.r_score = 4 THEN 'New & Promising'
           WHEN s.r_score = 2 THEN 'Needs Attention'
           WHEN s.r_score = 1 AND s.f_score = 1 THEN 'At Risk'
           ELSE 'Hibernating'
       END AS segment
FROM scored AS s;
